window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-16da43cf7f0ebc72"]={"versions": [{"id": "FIG-16da43cf7f0ebc72", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Einzelschritts „Write DataID“ innerhalb der Funktion <code>E2E_P04Forward()</code> der AUTOSAR E2E-Bibliothek (E2E Profile 4, AUTOSAR_PRS_E2EProtocol). Das Diagramm modelliert die absicherungsbezogene Einfügung der Daten-ID in die Nutzdaten vor dem Weitersenden über eine Gateway- oder Forwarding-Instanz.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätskontext / Funktion</strong>: <code>E2E_P04Forward()</code></li>\n<li><strong>Zustands- & Konfigurationsparameter</strong>:</li>\n<li><code>ForwardStatus</code>: Statusvariable zur Fehlerbewertung, verglichen mit Enumerator <code>E2E_P_ERROR</code></li>\n<li><code>Config-&gt;DataID</code>: 4-Byte-Konfigurationsidentifikator (<code>uint32</code>)</li>\n<li><code>Config-&gt;DataID+1</code>: Inkrementierter Datenbezeichner zur gezielten Fehlerübertragung / Ungültigmachung</li>\n<li><strong>Datenpuffer</strong>:</li>\n<li>Array bzw. Puffer <code>Data[]</code> mit Byte-Adressierung über <code>Data[Offset+4...Offset+7]</code> in Big-Endian-Byte-Reihenfolge (MSB first)</li>\n<li><strong>Ablaufknoten</strong>:</li>\n<li>Initialknoten (Start)</li>\n<li>Zwei Verzweigungsknoten (Decision- und Merge-Node als Rauten)</li>\n<li>Zwei Aktionsknoten zur Byte-Zuweisung</li>\n<li>Aktivitätsendknoten (Stop)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Initialknoten und führt zur ersten Verzweigung mit der Bedingung <code>if ForwardStatus == E2E_P_ERROR</code>.</li>\n<li>Evaluierung des Entscheidungsknotens:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>[TRUE]-Zweig</strong> (Fehlerstatus liegt vor): Ausführung der Aktion „Copy 4-byte Config->DataID+1 to bytes Data[Offset+4...Offset+7] in Big Endian order“.</li>\n<li><strong>[FALSE]-Zweig</strong> (kein Fehlerstatus): Ausführung der Aktion „Copy 4-byte Config->DataID to bytes Data[Offset+4...Offset+7] in Big Endian order“.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Pfade münden in den Merge-Knoten und terminieren am Aktivitätsendknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Schritt realisiert eine normative Verhaltensanforderung ([PRS_E2E_00618] gem. RS_E2E_08539) für E2E Profile 4 Forwarding:</p>\n<ul class=\"fig-list\">\n<li>Im Fehlerfall (<code>ForwardStatus == E2E_P_ERROR</code>) wird absichtlich ein verfälschter DataID-Wert (<code>DataID + 1</code>) in die Bytes <code>[Offset+4 ... Offset+7]</code> geschrieben, sodass nachfolgende E2E-Empfängerprüfungen (<code>E2E_P04Check()</code>) das Paket deterministisch als fehlerhaft verwerfen.</li>\n<li>Im regulären Fall (<code>[FALSE]</code>) wird die unveränderte <code>Config-&gt;DataID</code> geschrieben.</li>\n<li>Bei der Implementierung ist zwingend auf die netzwerkseitige Byte-Reihenfolge (Big Endian) über die 4 Bytes ab dem berechneten Byte-Offset zu achten.</li>\n</ul>"}, {"id": "FIG-c7db01daae5b4997", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Einzelschritts „Write DataID“ innerhalb der Funktion <code>E2E_P04Forward()</code> der AUTOSAR E2E-Bibliothek (E2E Profile 4, AUTOSAR_PRS_E2EProtocol). Das Diagramm modelliert die absicherungsbezogene Einfügung der Daten-ID in die Nutzdaten vor dem Weitersenden über eine Gateway- oder Forwarding-Instanz.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätskontext / Funktion</strong>: <code>E2E_P04Forward()</code></li>\n<li><strong>Zustands- & Konfigurationsparameter</strong>:</li>\n<li><code>ForwardStatus</code>: Statusvariable zur Fehlerbewertung, verglichen mit Enumerator <code>E2E_P_ERROR</code></li>\n<li><code>Config-&gt;DataID</code>: 4-Byte-Konfigurationsidentifikator (<code>uint32</code>)</li>\n<li><code>Config-&gt;DataID+1</code>: Inkrementierter Datenbezeichner zur gezielten Fehlerübertragung / Ungültigmachung</li>\n<li><strong>Datenpuffer</strong>:</li>\n<li>Array bzw. Puffer <code>Data[]</code> mit Byte-Adressierung über <code>Data[Offset+4...Offset+7]</code> in Big-Endian-Byte-Reihenfolge (MSB first)</li>\n<li><strong>Ablaufknoten</strong>:</li>\n<li>Initialknoten (Start)</li>\n<li>Zwei Verzweigungsknoten (Decision- und Merge-Node als Rauten)</li>\n<li>Zwei Aktionsknoten zur Byte-Zuweisung</li>\n<li>Aktivitätsendknoten (Stop)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Initialknoten und führt zur ersten Verzweigung mit der Bedingung <code>if ForwardStatus == E2E_P_ERROR</code>.</li>\n<li>Evaluierung des Entscheidungsknotens:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>[TRUE]-Zweig</strong> (Fehlerstatus liegt vor): Ausführung der Aktion „Copy 4-byte Config->DataID+1 to bytes Data[Offset+4...Offset+7] in Big Endian order“.</li>\n<li><strong>[FALSE]-Zweig</strong> (kein Fehlerstatus): Ausführung der Aktion „Copy 4-byte Config->DataID to bytes Data[Offset+4...Offset+7] in Big Endian order“.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Pfade münden in den Merge-Knoten und terminieren am Aktivitätsendknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Schritt realisiert eine normative Verhaltensanforderung ([PRS_E2E_00618] gem. RS_E2E_08539) für E2E Profile 4 Forwarding:</p>\n<ul class=\"fig-list\">\n<li>Im Fehlerfall (<code>ForwardStatus == E2E_P_ERROR</code>) wird absichtlich ein verfälschter DataID-Wert (<code>DataID + 1</code>) in die Bytes <code>[Offset+4 ... Offset+7]</code> geschrieben, sodass nachfolgende E2E-Empfängerprüfungen (<code>E2E_P04Check()</code>) das Paket deterministisch als fehlerhaft verwerfen.</li>\n<li>Im regulären Fall (<code>[FALSE]</code>) wird die unveränderte <code>Config-&gt;DataID</code> geschrieben.</li>\n<li>Bei der Implementierung ist zwingend auf die netzwerkseitige Byte-Reihenfolge (Big Endian) über die 4 Bytes ab dem berechneten Byte-Offset zu achten.</li>\n</ul>"}], "trans": [{"from": "FIG-16da43cf7f0ebc72", "to": "FIG-c7db01daae5b4997", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
